-- Each of the first three queries should return zero rows.
SELECT TABLE_NAME,CONSTRAINT_NAME,CONSTRAINT_TYPE FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME IN ('addresses','ai_conversations','ai_messages','audit_logs','cart_items','carts','categories','checkout_quotes','consumer_inbox','coupon_categories','coupon_products','coupon_redemptions','coupons','disputes','flash_sale_campaigns','flash_sale_items','flash_sale_purchases','idempotency_records','image','inventory','notification_templates','notifications','order_delivery_addresses','order_items','order_status_history','orders','outbox_events','password_reset_otp','payment_transactions','payments','permissions','product_embeddings','product_variants','products','refresh_tokens','refunds','return_items','return_requests','reviews','revoked_tokens','role','role_permissions','search_documents','seller_orders','shipments','shop_members','shops','stock_movements','stock_reservations','support_tickets','tracking_events','user','user_profile','user_role','warehouses') AND CONSTRAINT_TYPE <> 'PRIMARY KEY';
