SELECT TABLE_NAME,COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('addresses','ai_conversations','ai_messages','audit_logs','cart_items','carts','categories','checkout_quotes','consumer_inbox','coupon_categories','coupon_products','coupon_redemptions','coupons','disputes','flash_sale_campaigns','flash_sale_items','flash_sale_purchases','idempotency_records','image','inventory','notification_templates','notifications','order_delivery_addresses','order_items','order_status_history','orders','outbox_events','password_reset_otp','payment_transactions','payments','permissions','product_embeddings','product_variants','products','refresh_tokens','refunds','return_items','return_requests','reviews','revoked_tokens','role','role_permissions','search_documents','seller_orders','shipments','shop_members','shops','stock_movements','stock_reservations','support_tickets','tracking_events','user','user_profile','user_role','warehouses') AND IS_NULLABLE='NO' AND COLUMN_KEY <> 'PRI';
-- These diagnostic rows require application-level reconciliation; no rows are deleted automatically.
SELECT email,COUNT(*) AS duplicates FROM `user` GROUP BY email HAVING COUNT(*)>1;
SELECT user_id,role_name,COUNT(*) AS duplicates FROM user_role GROUP BY user_id,role_name HAVING COUNT(*)>1;
SELECT oi.order_item_id FROM order_items oi LEFT JOIN orders o ON o.order_id=oi.order_id WHERE oi.order_id IS NOT NULL AND o.order_id IS NULL;
